"""Resumable, rate-limit- and token-aware fetcher for the order service.

Usage:
  python3 -I fetch.py orders    <datadir>
  python3 -I fetch.py customers <datadir> <ids-file>

Raw response bodies are written under <datadir>; every non-200 response is logged
to <datadir>/events.log. Requests are strictly sequential.
"""
import http.client
import json
import os
import socket
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 80
NOT_FOUND = object()


class Client:
    def __init__(self, datadir):
        self.token = None
        self.tokens_issued = 0
        self.requests = 0
        self.logf = open(os.path.join(datadir, "events.log"), "a", buffering=1)

    def log(self, msg):
        line = "%s %s" % (time.strftime("%H:%M:%S"), msg)
        print(line, flush=True)
        self.logf.write(line + "\n")

    def _send(self, method, path, token):
        req = urllib.request.Request(BASE + path, method=method,
                                     data=b"" if method == "POST" else None)
        if token:
            req.add_header("Authorization", "Bearer " + token)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()
        except (urllib.error.URLError, http.client.HTTPException,
                socket.timeout, OSError) as e:
            return None, {}, repr(e).encode()

    @staticmethod
    def _retry_after(headers, body):
        waits = []
        for k, v in headers.items():
            if k.lower() == "retry-after":
                try:
                    waits.append(float(v))
                except ValueError:
                    pass
        try:
            j = json.loads(body)
            if isinstance(j, dict) and isinstance(j.get("retry_after"), (int, float)):
                waits.append(float(j["retry_after"]))
        except ValueError:
            pass
        return max(waits) if waits else None

    def request(self, method, path, auth=True, validate=None, allow_404=False):
        """Return (parsed_json, raw_text), or (NOT_FOUND, raw_text) for a confirmed 404."""
        not_found_seen = 0
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.token = self._new_token()
            status, headers, body = self._send(method, path, self.token if auth else None)
            self.requests += 1
            text = body.decode("utf-8", "replace")

            if status == 200:
                try:
                    data = json.loads(text)
                except ValueError:
                    data = None
                if data is not None and (validate is None or validate(data)):
                    return data, text
                self.log("BAD200 %s %s attempt=%d body=%.200r" % (method, path, attempt, text))
                time.sleep(1.0)
                continue

            self.log("HTTP %s %s %s attempt=%d body=%.200r" % (status, method, path, attempt, text))

            if status == 429:
                wait = self._retry_after(headers, body)
                if wait is None:
                    wait = 2.0
                    self.log("  429 without a parseable Retry-After; defaulting to %.1fs" % wait)
                time.sleep(wait + 0.1)
            elif status == 401:
                self.token = None          # expired / invalid: get a fresh one and retry
            elif status == 404 and allow_404:
                not_found_seen += 1
                if not_found_seen >= 3:     # confirmed, not transient
                    return NOT_FOUND, text
                time.sleep(0.5)
            else:                           # 5xx, network error, anything unexpected
                time.sleep(min(0.25 * 2 ** min(attempt, 5), 5.0))
