    missing = [n for n in range(1, total_pages + 1) if n not in fetched]
    for n in missing:
        client.log("NOTE page %d not reached via `next`; fetching directly" % n)
        data, text = client.request("GET", "/orders?page=%d" % n, validate=valid_orders_page)
        with open(os.path.join(odir, "page-%03d.json" % data["page"]), "w") as f:
            f.write(text)
        fetched[data["page"]] = len(data["items"])
    client.log("DONE orders: %d pages, %d listed items" % (len(fetched), sum(fetched.values())))


def fetch_customers(client, datadir, ids_file):
    cdir = os.path.join(datadir, "customers")
    os.makedirs(cdir, exist_ok=True)
    ids = [l.strip() for l in open(ids_file) if l.strip()]
    for i, cid in enumerate(ids, 1):
        fn = os.path.join(cdir, "%s.json" % cid)
        if os.path.exists(fn):
            continue                        # keep results around; one lookup per customer
        data, text = client.request("GET", "/customers/%s" % cid,
                                    validate=valid_customer, allow_404=True)
        if data is NOT_FOUND:
            text = json.dumps({"id": cid, "_http_status": 404, "_body": text})
            client.log("customer %s: 404 confirmed" % cid)
